record Item(int weight, int value) {
    Item {
        Validation.requireNonNegative(weight, "weight");
        Validation.requireNonNegative(value, "value");
    }
}

import java.util.List;
import java.util.Objects;

record Problem(int capacity, List<Item> items) {
    Problem {
        Validation.requireNonNegative(capacity, "capacity");
        Objects.requireNonNull(items, "items must not be null");
        items = List.copyOf(items);
    }

    static Problem of(int capacity, List<Item> items) {
        Objects.requireNonNull(items, "items must not be null");
        return new Problem(capacity, items);
    }

    static Problem of(int capacity, Item... items) {
        Objects.requireNonNull(items, "items must not be null");
        return of(capacity, List.of(items));
    }
}

import java.util.List;
import java.util.Objects;

final class Problems {
    private Problems() {
    }

    static Problem fromParallelArrays(int capacity, int[] values, int[] weights) {
        validateParallelArrays(values, weights);
        return Problem.of(capacity, toItems(values, weights));
    }

    static Problem sampleProblem() {
        return Problem.of(4,
                new Item(4, 1),
                new Item(5, 2),
                new Item(1, 3)
        );
    }

    private static void validateParallelArrays(int[] values, int[] weights) {
        Objects.requireNonNull(values, "values must not be null");
        Objects.requireNonNull(weights, "weights must not be null");

        if (values.length != weights.length) {
            throw new IllegalArgumentException("values and weights must have the same length");
        }
    }

    private static List<Item> toItems(int[] values, int[] weights) {
        Item[] items = new Item[values.length];

        for (int index = 0; index < values.length; index++) {
            items[index] = new Item(weights[index], values[index]);
        }

        return List.of(items);
    }
}

final class CapacityTable {
    private final int[] bestValues;

    CapacityTable(int capacity) {
        this.bestValues = new int[capacity + 1];
    }

    private int bestValueAt(int capacity) {
        return bestValues[capacity];
    }

    void consider(Item item) {
        for (int capacity = bestValues.length - 1; capacity >= item.weight(); capacity--) {
            int candidateValue = bestValueAt(capacity - item.weight()) + item.value();
            bestValues[capacity] = Math.max(bestValues[capacity], candidateValue);
        }
    }

    KnapsackSolution solutionFor(Problem problem) {
        return new KnapsackSolution(problem, bestValueAt(problem.capacity()));
    }
}

import java.util.Objects;

record KnapsackSolution(Problem problem, int optimalValue) {
    KnapsackSolution {
        Objects.requireNonNull(problem, "problem must not be null");
        Validation.requireNonNegative(optimalValue, "optimalValue");
    }
}

final class DynamicProgrammingSolver implements KnapsackSolver {

    @Override
    public KnapsackSolution solve(Problem problem) {
        CapacityTable capacityTable = new CapacityTable(problem.capacity());

        for (Item item : problem.items()) {
            capacityTable.consider(item);
        }

        return capacityTable.solutionFor(problem);
    }
}

final class Validation {
    private Validation() {
    }

    static void requireNonNegative(int value, String name) {
        if (value < 0) {
            throw new IllegalArgumentException(name + " must be non-negative");
        }
    }
}

import java.util.List;

class Knapsack {
    private static final KnapsackSolver SOLVER = new DynamicProgrammingSolver();

    private Knapsack() {
    }

    static int knapsack(int capacity, int[] values, int[] weights) {
        return maxValue(Problems.fromParallelArrays(capacity, values, weights));
    }

    static int maxValue(int capacity, Item... items) {
        return solve(capacity, items).optimalValue();
    }

    static int maxValue(int capacity, List<Item> items) {
        return solve(capacity, items).optimalValue();
    }

    static int maxValue(Problem problem) {
        return solve(problem).optimalValue();
    }

    static KnapsackSolution solve(int capacity, Item... items) {
        return solve(Problem.of(capacity, items));
    }

    static KnapsackSolution solve(int capacity, List<Item> items) {
        return solve(Problem.of(capacity, items));
    }

    static KnapsackSolution solve(Problem problem) {
        return SOLVER.solve(problem);
    }

    public static void main(String[] args) {
        Problem problem = Problems.sampleProblem();

        System.out.println(solve(problem).optimalValue());
    }
}

